gvz(){return"\u0ca8\u0cbe\u0cb5\u0cc1 \u0cb0\u0cc6\u0c97\u0ccd\u0caf\u0cc1\u0cb2\u0cb0\u0cc8\u0cb8\u0cc7\u0cb6\u0ca8\u0ccd \u0cb0\u0cbf\u0c95\u0ccd\u0cb5\u0cc6\u0cb8\u0ccd\u0c9f\u0ccd \u0c85\u0caa\u0ccd\u200c\u0ca1\u0cc7\u0c9f\u0ccd \u0cae\u0cbe\u0ca1\u0cb2\u0cc1 \u0cb8\u0cbe\u0ca7\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gvA(){return"\u0cb0\u0cc6\u0c97\u0ccd\u0caf\u0cc1\u0cb2\u0cb0\u0cc8\u0cb8\u0cc7\u0cb6\u0ca8\u0ccd \u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf \u0c85\u0caa\u0ccd\u200c\u0ca1\u0cc7\u0c9f\u0ccd \u0c86\u0c97\u0cbf\u0ca6\u0cc6."},
gvd(){return"\u0ca8\u0cbe\u0cb5\u0cc1 \u0c8e\u0cb5\u0cbf\u0ca1\u0cc6\u0ca8\u0ccd\u0cb8\u0ccd \u0cab\u0cc8\u0cb2\u0ccd \u0ca4\u0cc6\u0cb0\u0cc6\u0caf\u0cb2\u0cc1 \u0cb8\u0cbe\u0ca7\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gvb(){return"\u0cb2\u0cca\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0c85\u0ca8\u0ccd\u0ca8\u0cc1 \u0c89\u0ca6\u0ccd\u0caf\u0ccb\u0c97\u0cbf\u0c97\u0cc6 \u0ca8\u0cbf\u0caf\u0ccb\u0c9c\u0cbf\u0cb8\u0cb2\u0cbe\u0c97\u0cbf\u0ca6\u0cc6."},
